# Rubriques déclaratives de la fiche de cession selon la nature du lot
DECLARATIONS_BASE = [
    "Produits identifiés et traçables",
    "Produits sûrs et non interdits à la vente",
    "Étiquetage et mentions obligatoires présents",
    "Aucun rappel / retrait connu à la date de cession",
]
DECLARATIONS_FOOD = [
    "DLC / DDM compatible avec la remise prévue",
    "Allergènes / composition communiqués",
    "Température et chaîne du froid conformes",
]
DECLARATIONS_HYGIENE = [
    "Notice / avertissements en français remis",
    "Fiche de données de sécurité jointe si applicable",
]
DECLARATIONS_EQUIPMENT = [
    "Garantie commerciale / fabricant précisée",
    "Notice / avertissements en français remis",
    "Marquage ou certification applicable vérifié",
]
DECLARATIONS_USED = ["Défauts d'occasion / reconditionné décrits"]

FOOD_KEYWORDS = ("alim", "épicerie", "epicerie", "frais", "surgel", "boisson", "cuisine")
HYGIENE_KEYWORDS = ("hygi", "cosm", "entretien")
EQUIPMENT_KEYWORDS = ("équip", "equip", "électro", "electro", "bazar", "maison", "mobil", "auto", "btp", "matéri", "materi")


def cession_declarations(category: str, perishable: bool, condition: str) -> list:
    cat = (category or "").lower()
    decls = list(DECLARATIONS_BASE)
    if perishable or any(k in cat for k in FOOD_KEYWORDS):
        decls += DECLARATIONS_FOOD
    if any(k in cat for k in HYGIENE_KEYWORDS):
        decls += DECLARATIONS_HYGIENE
    if any(k in cat for k in EQUIPMENT_KEYWORDS):
        decls += DECLARATIONS_EQUIPMENT
    if (condition or "NEW") != "NEW":
        decls += DECLARATIONS_USED
    return list(dict.fromkeys(decls))
